<?php
require_once __DIR__.'/comercial.php';
$rows=query('SELECT * FROM clientes WHERE ?=1 OR criado_por=? ORDER BY nome',[admin()?1:0,$_SESSION['user']['id']])->fetchAll();
$edit=null;if(isset($_GET['editar'])){try{$edit=clientePermitido((int)$_GET['editar']);}catch(Throwable $ex){http_response_code(404);exit('Cliente não encontrado.');}}
page('Clientes');?>
<section class="card"><h2><?=$edit?'Editar cliente':'Cadastrar cliente'?></h2><form method="post" class="form-grid" data-company-form><?php csrf();?><input type="hidden" name="action" value="save_customer"><input type="hidden" name="id" value="<?=$edit['id']??0?>">
<label>Tipo<select name="tipo" data-client-type><option value="PF" <?=($edit['tipo']??'PF')==='PF'?'selected':''?>>Pessoa física</option><option value="PJ" <?=($edit['tipo']??'')==='PJ'?'selected':''?>>Empresa</option></select></label>
<label>CPF / CNPJ<input name="documento" data-cnpj required maxlength="18" value="<?=e($edit['documento']??'')?>"></label><div class="company-action"><button type="button" data-cnpj-search class="secondary">Consultar CNPJ</button></div><p data-cnpj-status role="status" aria-live="polite">Para empresas, consulte o CNPJ e confira os dados.</p>
<label>Nome / razão social<input name="nome" data-company-name required maxlength="150" value="<?=e($edit['nome']??'')?>"></label><label>E-mail (opcional)<input type="email" name="email" data-company-email maxlength="190" value="<?=e($edit['email']??'')?>"></label><label>Telefone (opcional)<input name="telefone" data-company-phone maxlength="30" value="<?=e($edit['telefone']??'')?>"></label><div class="form-footer"><button>Salvar cliente</button><a href="index.php?p=clientes">Limpar</a></div></form></section>
<section class="card"><div class="table-wrap"><table><thead><tr><th>Nome</th><th>Tipo</th><th>CPF / CNPJ</th><th>Contato</th><th>Ação</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['nome'])?></td><td><?=$r['tipo']==='PJ'?'Empresa':'Pessoa física'?></td><td><?=e($r['documento'])?></td><td><?=e($r['email'])?><small><?=e($r['telefone'])?></small></td><td><a href="index.php?p=clientes&editar=<?=$r['id']?>">Editar</a></td></tr><?php endforeach;if(!$rows)emptyRow(5);?></tbody></table></div></section><?php endpage();
